const assert = require('node:assert/strict');
const { EventService } = require('../.build/service');

// Implements the Source / Lease interface from src/source.ts.
function fixture({ values = ['a', 'b', null], read, closeError, mapper } = {}) {
  const calls = { opens: 0, reads: 0, closes: 0 };
  const source = {
    async open() {
      calls.opens++;
      return {
        async read() {
          calls.reads++;
          return read ? read() : values.shift();
        },
        async close() {
          calls.closes++;
          if (closeError) throw closeError;
        },
      };
    },
  };
  return { calls, stream: new EventService(source, mapper).stream() };
}

async function rejectsWith(promise, error) {
  await assert.rejects(promise, actual => Object.is(actual, error));
}

async function main() {
  {
    const { calls, stream } = fixture();
    assert.deepEqual(calls, { opens: 0, reads: 0, closes: 0 });
    await stream.return();
    assert.deepEqual(calls, { opens: 0, reads: 0, closes: 0 });
  }
  {
    const { calls, stream } = fixture();
    assert.deepEqual(await stream.next(), { value: 'A', done: false });
    await new Promise(resolve => setImmediate(resolve));
    assert.deepEqual(calls, { opens: 1, reads: 1, closes: 0 });
    assert.deepEqual(await stream.next(), { value: 'B', done: false });
    assert.equal(calls.reads, 2);
    assert.deepEqual(await stream.next(), { value: undefined, done: true });
    assert.deepEqual(calls, { opens: 1, reads: 3, closes: 1 });
    await stream.next();
    await stream.return();
    assert.deepEqual(calls, { opens: 1, reads: 3, closes: 1 });
  }
  {
    const { calls, stream } = fixture();
    const found = [];
    for await (const value of stream) found.push(value);
    assert.deepEqual(found, ['A', 'B']);
    assert.equal(calls.closes, 1);
  }
  for (const closeError of [undefined, new Error('close failed')]) {
    for (const exit of ['exhaustion', 'break', 'return']) {
      const { calls, stream } = fixture({ closeError });
      const consume = async () => {
        if (exit === 'return') {
          await stream.next();
          return stream.return('returned');
        }
        for await (const value of stream) {
          if (exit === 'break') break;
        }
      };
      if (closeError) await rejectsWith(consume(), closeError);
      else await consume();
      assert.deepEqual(calls, {
        opens: 1, reads: exit === 'exhaustion' ? 3 : 1, closes: 1,
      });
      await stream.return();
      assert.equal(calls.closes, 1);
    }
    for (const failure of ['read', 'mapper', 'throw']) {
      // Include undefined to ensure precedence does not depend on truthiness.
      for (const original of [new Error(failure), undefined]) {
        const { calls, stream } = fixture({
          closeError,
          read: failure === 'read' ? () => { throw original; } : undefined,
          mapper: failure === 'mapper' ? () => { throw original; } : undefined,
        });
        if (failure === 'throw') {
          await stream.next();
          await rejectsWith(stream.throw(original), original);
        } else {
          await rejectsWith(stream.next(), original);
        }
        assert.deepEqual(calls, { opens: 1, reads: 1, closes: 1 });
        await stream.next();
        await stream.return();
        assert.equal(calls.closes, 1);
      }
    }
  }
  {
    const error = new Error('open failed');
    let opens = 0;
    const stream = new EventService({ open: async () => { opens++; throw error; } }).stream();
    await rejectsWith(stream.next(), error);
    await stream.return();
    assert.equal(opens, 1);
  }
}

module.exports = main();
EOF
